style.css:
/* kitty archive — Roblox */
:root {
  /* можешь менять эти цвета */
  --my-bg: #242321;
  --my-card: #33312e;
  --my-accent: #c9b9a5;
  --my-text: #eee9e2;
  --my-muted: #a9a197;
}

/* фон */
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* карточки и панели */
section,
article,
[role="dialog"] {
  background-color: var(--my-card) !important;
  border-radius: 16px !important;
}

/* кнопки */
button {
  border-radius: 12px !important;
  transition: 0.2s ease !important;
}

/* акцентные кнопки */
button:hover {
  filter: brightness(1.12) !important;
  transform: translateY(-1px);
}

/* ссылки */
a {
  color: var(--my-accent) !important;
  transition: 0.2s ease;
}

/* поля ввода */
input,
textarea {
  background: #292724 !important;
  color: var(--my-text) !important;
  border: 1px solid #514b44 !important;
  border-radius: 10px !important;
}

/* изображения */
img {
  border-radius: 10px;
}

/* скролл */
::-webkit-scrollbar {
  width: 7px;
}

::-webkit-scrollbar-thumb {
  background: #766b5e;
  border-radius: 10px;
}

::-webkit-scrollbar-track {
  background: var(--my-bg);
}
